    ensures sum == Sum(numbers) // The sum of all integers in the list
    ensures product == Product(numbers) // The product of all integers in the list
    ensures (|numbers| == 0 ==> sum == 0 && product == 1) // If the list is empty, sum should be 0 and product should be 1
