function Sum(numbers: Seq<int>): int
{
    var s := 0;
    var i := 0;
    while i < |numbers|
        invariant 0 <= i <= |numbers|
        invariant s == Sum(numbers[0..i]) // The sum of the first i elements
    {
        s := s + numbers[i];
        i := i + 1;
    }
    return s;
}

function Product(numbers: Seq<int>): int
{
    var p := 1;
    var i := 0;
    while i < |numbers|
        invariant 0 <= i <= |numbers|
        invariant p == Product(numbers[0..i]) // The product of the first i elements
    {
        p := p * numbers[i];
        i := i + 1;
    }
    return p;
}

